1	<!DOCTYPE html>
2	<html lang="mk">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Зелена Империја — од семка до берба</title>
7	<style>
8	/* ═══════════════════════════════════════════════════════════════
9	   ЗЕЛЕНА ИМПЕРИЈА — стилови
10	   ═══════════════════════════════════════════════════════════════ */
11	:root{
12	  --pozadina:#0e1611; --panel:#16221b; --panel-2:#1d2d24; --rab:#2b4034;
13	  --tekst:#e8f2ea; --tekst-slab:#8fa899; --zelena:#4ade80; --zelena-temna:#22c55e;
14	  --zlato:#fbbf24; --crvena:#f87171; --sina:#60a5fa; --violet:#c084fc;
15	  --r:12px; --sen:0 4px 20px rgba(0,0,0,.4);
16	}
17	*{box-sizing:border-box;margin:0;padding:0}
18	body{
19	  background:radial-gradient(ellipse at 50% -10%,#1c3527 0%,var(--pozadina) 60%);
20	  color:var(--tekst); font-family:"Segoe UI",Roboto,system-ui,sans-serif;
21	  min-height:100vh; padding:14px; font-size:14px;
22	}
23	button{font-family:inherit;cursor:pointer;border:none;border-radius:8px;
24	  transition:transform .08s,filter .15s}
25	button:hover:not(:disabled){filter:brightness(1.15)}
26	button:active:not(:disabled){transform:translateY(1px)}
27	button:disabled{opacity:.35;cursor:not-allowed}
28	
29	/* ── Заглавие ───────────────────────────────────────────────── */
30	.zaglavje{
31	  display:flex;flex-wrap:wrap;gap:10px;align-items:center;
32	  background:linear-gradient(135deg,var(--panel-2),var(--panel));
33	  border:1px solid var(--rab);border-radius:var(--r);padding:12px 16px;
34	  margin-bottom:14px;box-shadow:var(--sen)
35	}
36	.logo{font-size:19px;font-weight:800;letter-spacing:.3px;
37	  background:linear-gradient(90deg,var(--zelena),var(--zlato));
38	  -webkit-background-clip:text;background-clip:text;color:transparent;white-space:nowrap}
39	.hud{display:flex;flex-wrap:wrap;gap:8px;margin-left:auto;align-items:center}
40	.stat{background:#0d1712;border:1px solid var(--rab);border-radius:9px;
41	  padding:6px 12px;display:flex;flex-direction:column;gap:2px;min-width:88px}
42	.stat b{font-size:15px;line-height:1}
43	.stat span{font-size:10px;color:var(--tekst-slab);text-transform:uppercase;letter-spacing:.5px}
44	.xp-lenta{height:4px;background:#0d1712;border-radius:3px;overflow:hidden;
45	  width:110px;border:1px solid var(--rab)}
46	.xp-lenta>i{display:block;height:100%;background:linear-gradient(90deg,var(--violet),var(--sina));
47	  transition:width .3s}
48	
49	/* ── Распоред ───────────────────────────────────────────────── */
50	.raspored{display:grid;grid-template-columns:1fr 370px;gap:14px;align-items:start}
51	@media(max-width:1020px){.raspored{grid-template-columns:1fr}}
52	
53	/* ── Леи ────────────────────────────────────────────────────── */
54	.lei{display:grid;grid-template-columns:repeat(auto-fill,minmax(178px,1fr));gap:12px}
55	.leja{background:var(--panel);border:1px solid var(--rab);border-radius:var(--r);
56	  padding:10px;display:flex;flex-direction:column;gap:8px;box-shadow:var(--sen)}
57	.leja.zaklucena{opacity:.55;border-style:dashed}
58	.leja.zrela{border-color:var(--zlato);box-shadow:0 0 0 1px var(--zlato),0 4px 20px rgba(251,191,36,.18)}
59	.leja.bolna{border-color:var(--crvena)}
60	.leja-glava{display:flex;justify-content:space-between;align-items:baseline;gap:6px}
61	.leja-br{font-size:11px;color:var(--tekst-slab);text-transform:uppercase;letter-spacing:.6px}
62	.leja-faza{font-size:11px;font-weight:700;color:var(--zelena)}
63	.leja.zrela .leja-faza{color:var(--zlato)}
64	
65	/* Сцена со растение */
66	.scena{position:relative;height:132px;border-radius:9px;overflow:hidden;
67	  background:linear-gradient(180deg,#0b1a13 0%,#102a1c 68%,#3a2a18 68%,#291d10 100%)}
68	.scena svg{position:absolute;inset:0;width:100%;height:100%}
69	.scena svg g{transition:transform .3s ease-out,opacity .4s}
70	.znak-sorta{position:absolute;top:5px;left:6px;font-size:9px;font-weight:700;
71	  color:var(--tekst-slab);background:rgba(0,0,0,.45);padding:2px 5px;border-radius:4px}
72	.znak-stetnik{position:absolute;top:5px;right:6px;font-size:15px;
73	  animation:trepka 1.1s infinite;cursor:help}
74	@keyframes trepka{0%,100%{opacity:1}50%{opacity:.35}}
75	.prazna-poraka{position:absolute;inset:0;display:flex;align-items:center;
76	  justify-content:center;color:var(--tekst-slab);font-size:12px;text-align:center;padding:8px}
77	
78	/* Ленти за статус */
79	.lenti{display:flex;flex-direction:column;gap:4px}
80	.lenta{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--tekst-slab)}
81	.lenta i{font-style:normal;width:14px;text-align:center}
82	.lenta .zica{flex:1;height:6px;background:#0d1712;border-radius:4px;overflow:hidden;
83	  border:1px solid var(--rab)}
84	.lenta .zica>b{display:block;height:100%;border-radius:3px;transition:width .25s,background .25s}
85	.lenta u{text-decoration:none;width:26px;text-align:right;font-variant-numeric:tabular-nums}
86	
87	/* Дугмиња на леја */
88	.akcii{display:grid;grid-template-columns:1fr 1fr;gap:5px}
89	.akcii button{font-size:11px;font-weight:700;padding:7px 4px;
90	  background:var(--panel-2);color:var(--tekst);border:1px solid var(--rab)}
91	.akcii button.glavna{grid-column:1/-1;background:linear-gradient(135deg,var(--zelena-temna),#15803d);
92	  color:#04150b;border-color:transparent}
93	.akcii button.zlatna{grid-column:1/-1;background:linear-gradient(135deg,var(--zlato),#d97706);
94	  color:#2a1a00;border-color:transparent}
95	.akcii button.opasna{grid-column:1/-1;background:linear-gradient(135deg,var(--crvena),#dc2626);
96	  color:#2a0606;border-color:transparent}
97	
98	/* ── Странични панели ───────────────────────────────────────── */
99	.strana{background:var(--panel);border:1px solid var(--rab);border-radius:var(--r);
100	  box-shadow:var(--sen);overflow:hidden;position:sticky;top:14px}
101	.jazicinja{display:flex;background:#0d1712;border-bottom:1px solid var(--rab)}
102	.jazicinja button{flex:1;padding:11px 4px;font-size:11.5px;font-weight:700;
103	  background:transparent;color:var(--tekst-slab);border-radius:0;border-bottom:2px solid transparent}
104	.jazicinja button.aktivno{color:var(--zelena);border-bottom-color:var(--zelena);background:var(--panel)}
105	.sodrzina{padding:12px;max-height:calc(100vh - 190px);overflow-y:auto}
106	.sodrzina::-webkit-scrollbar{width:7px}
107	.sodrzina::-webkit-scrollbar-thumb{background:var(--rab);border-radius:4px}
108	
109	.stavka{background:var(--panel-2);border:1px solid var(--rab);border-radius:9px;
110	  padding:9px 10px;margin-bottom:8px;display:flex;flex-direction:column;gap:6px}
111	.stavka.zakluceno{opacity:.5}
112	.stavka-glava{display:flex;justify-content:space-between;align-items:center;gap:8px}
113	.stavka-ime{font-weight:700;font-size:13px}
114	.stavka-cena{color:var(--zlato);font-weight:800;font-size:13px;white-space:nowrap}
115	.stavka-opis{font-size:11px;color:var(--tekst-slab);line-height:1.45}
116	.stavka button{padding:7px;font-size:11.5px;font-weight:700;
117	  background:linear-gradient(135deg,var(--zelena-temna),#15803d);color:#04150b}
118	.stavka button.sina{background:linear-gradient(135deg,var(--sina),#2563eb);color:#03142c}
119	.stavka .dve{display:grid;grid-template-columns:1fr 1fr;gap:6px}
120	.prazno{color:var(--tekst-slab);font-size:12px;text-align:center;padding:26px 10px;line-height:1.6}
121	
122	.oznaka{display:inline-block;padding:2px 7px;border-radius:20px;font-size:10px;font-weight:800}
123	.o-vrven{background:rgba(251,191,36,.18);color:var(--zlato)}
124	.o-odlicen{background:rgba(74,222,128,.18);color:var(--zelena)}
125	.o-sreden{background:rgba(96,165,250,.18);color:var(--sina)}
126	.o-slab{background:rgba(248,113,113,.18);color:var(--crvena)}
127	
128	.napredok{height:6px;background:#0d1712;border:1px solid var(--rab);
129	  border-radius:4px;overflow:hidden}
130	.napredok>i{display:block;height:100%;background:linear-gradient(90deg,var(--zlato),#f59e0b);
131	  transition:width .3s}
132	
133	/* ── Известувања ────────────────────────────────────────────── */
134	.izvestuvanja{position:fixed;right:14px;bottom:14px;display:flex;flex-direction:column;
135	  gap:7px;z-index:60;max-width:310px;pointer-events:none}
136	.toast{background:var(--panel-2);border:1px solid var(--rab);border-left:3px solid var(--zelena);
137	  border-radius:8px;padding:9px 13px;font-size:12.5px;box-shadow:var(--sen);
138	  animation:vlez .25s ease-out}
139	.toast.greska{border-left-color:var(--crvena)}
140	.toast.pari{border-left-color:var(--zlato)}
141	@keyframes vlez{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}
142	
143	/* ── Модал ──────────────────────────────────────────────────── */
144	.modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;
145	  align-items:center;justify-content:center;z-index:80;padding:18px}
146	.modal.otvoren{display:flex}
147	.modal-kutija{background:var(--panel);border:1px solid var(--rab);border-radius:var(--r);
148	  padding:18px;max-width:430px;width:100%;max-height:82vh;overflow-y:auto;box-shadow:var(--sen)}
149	.modal-naslov{font-size:16px;font-weight:800;margin-bottom:12px}
150	.modal-zatvori{width:100%;padding:9px;margin-top:6px;background:var(--panel-2);
151	  color:var(--tekst-slab);border:1px solid var(--rab);font-weight:700;font-size:12px}
152	</style>
153	</head>
154	<body>
155	
156	<header class="zaglavje">
157	  <div class="logo">🌿 ЗЕЛЕНА ИМПЕРИЈА</div>
158	  <div class="hud">
159	    <div class="stat"><b id="hud-pari">0</b><span>Денари</span></div>
160	    <div class="stat"><b id="hud-nivo">1</b><span>Ниво</span><div class="xp-lenta"><i id="hud-xp"></i></div></div>
161	    <div class="stat"><b id="hud-den">1</b><span>Ден</span></div>
162	    <div class="stat"><b id="hud-lampa">Флуо</b><span>Ламба</span></div>
163	    <div class="stat"><b id="hud-grama">0 г</b><span>Вкупна берба</span></div>
164	  </div>
165	</header>
166	
167	<div class="raspored">
168	  <main class="lei" id="lei"></main>
169	
170	  <aside class="strana">
171	    <nav class="jazicinja">
172	      <button data-jaz="prodavnica" class="aktivno">Продавница</button>
173	      <button data-jaz="sushara">Сушара</button>
174	      <button data-jaz="magacin">Магацин</button>
175	      <button data-jaz="nadgradbi">Надградби</button>
176	    </nav>
177	    <div class="sodrzina" id="sodrzina"></div>
178	  </aside>
179	</div>
180	
181	<div class="izvestuvanja" id="izvestuvanja"></div>
182	
183	<div class="modal" id="modal">
184	  <div class="modal-kutija">
185	    <div class="modal-naslov" id="modal-naslov"></div>
186	    <div id="modal-telo"></div>
187	    <button class="modal-zatvori" onclick="zatvoriModal()">Затвори</button>
188	  </div>
189	</div>
190	
191	<script>
192	"use strict";
193	/* ═══════════════════════════════════════════════════════════════
194	   1. КОНФИГУРАЦИЈА
195	   ═══════════════════════════════════════════════════════════════ */
196	const KONFIG = {
197	  TIK_MS: 250,            // реални милисекунди по тик
198	  CHASA_PO_TIK: 3,        // игрални часови по тик  →  8 тика = 1 ден = 2 сек
199	  MAX_TIKOVI_NADOMEST: 8, // капа за наваксување кога табот бил во заднина
200	  AVTOSEJV_TIKOVI: 40,    // зачувај на секои 10 реални секунди
201	  KLUC_SEJV: "zelena-imperija-sejv",
202	  VERZIJA: 1,
203	
204	  POCETNI_PARI: 8000,
205	  POCETNI_LEI: 4,
206	  MAX_LEI: 12,
207	  CENA_LEJA_OSNOVA: 75000,
208	  CENA_LEJA_RAST: 1.6,
209	
210	  // Времетраење на фазите во игрални часови (пред множителот `traenje`)
211	  CHASA_NIKNENJE: 3 * 24,
212	  CHASA_VEGETACIJA: 21 * 24,
213	  CHASA_CVETANJE: 50 * 24,
214	  CHASA_ZRELO_PROZOR: 14 * 24,
215	
216	  // Грижа
217	  VODA_PAD_DEN: 6, HRANA_PAD_DEN: 3,
218	  VODA_DOZA: 45, HRANA_DOZA: 40, CENA_HRANA: 250,
219	  VODA_MIN: 20, VODA_MAX: 95, HRANA_MIN: 15, HRANA_MAX: 95,
220	  AVTO_VODA_PRAG: 55, RABOTNIK_PRAG: 40,
221	
222	  // Здравје — промена по тик
223	  STETA_SUSA: 1.2, STETA_DAVENJE: 0.8,
224	  STETA_GLAD: 0.9, STETA_PREGOR: 0.6,
225	  OPORAVUVANJE: 0.4,
226	  KAZNA_PREZRELOST_DEN: 1.5,
227	
228	  SANSA_STETNIK_DEN: 0.03, KLIMA_NAMALUVANJE: 0.4,
229	  SUSHARA_ZABRZUVANJE: 1.4,
230	  VLAZNO_VO_SUVO: 0.22,       // мокра маса → сува маса
231	  CENA_LABORATORIJA: 900, BONUS_LABORATORIJA: 1.18,
232	  PAZAR_DRIFT: 0.03, PAZAR_MIN: 0.75, PAZAR_MAX: 1.35
233	};
234	
235	/* ═══════════════════════════════════════════════════════════════
236	   2. СОДРЖИНА — сортите, ламбите, надградбите, штетниците
237	   Балансот се менува ТУКА, не во логиката подолу.
238	   ═══════════════════════════════════════════════════════════════ */
239	
240	// traenje = множител на времетраењето. 0.85 значи 15% ПОБРЗО,
241	// 1.35 значи 35% ПОБАВНО. Скапите сорти растат побавно, но даваат повеќе.
242	const SORTI = [
243	  {id:"skopsko", ime:"Скопско Зелено",     cena:150,  traenje:0.85, prinos:60,  genetika:0.45, cenaPoGram:90,  nivo:1},
244	  {id:"vardar",  ime:"Вардар Куш",         cena:400,  traenje:1.00, prinos:85,  genetika:0.60, cenaPoGram:140, nivo:2},
245	  {id:"pelister",ime:"Пелистерска Магла",  cena:900,  traenje:1.10, prinos:110, genetika:0.72, cenaPoGram:200, nivo:4},
246	  {id:"ohrid",   ime:"Охридски Кристал",   cena:1800, traenje:1.15, prinos:130, genetika:0.82, cenaPoGram:280, nivo:6},
247	  {id:"shar",    ime:"Шар Планина Хаза",   cena:3200, traenje:1.25, prinos:155, genetika:0.90, cenaPoGram:380, nivo:8},
248	  {id:"dojran",  ime:"Дојранска Ноќ",      cena:6000, traenje:1.35, prinos:185, genetika:0.97, cenaPoGram:520, nivo:11}
249	];
250	
251	const LAMPI = [
252	  {id:"fluo", ime:"Флуо",                cena:0,     prinosMult:1.00, kvalitetBonus:0,  nivo:1},
253	  {id:"hps",  ime:"ХПС",                 cena:220000,prinosMult:1.15, kvalitetBonus:4,  nivo:2},
254	  {id:"led",  ime:"ЛЕД",                 cena:700000,prinosMult:1.30, kvalitetBonus:8,  nivo:5},
255	  {id:"leds", ime:"ЛЕД Full-Spectrum",   cena:2400000,prinosMult:1.50, kvalitetBonus:14, nivo:9}
256	];
257	
258	const NADGRADBI = [
259	  {id:"navodnuvanje", ime:"Автоматско наводнување", cena:240000,
260	   opis:"Водата никогаш не паѓа под 55%. Крајот на рачното полевање."},
261	  {id:"klima", ime:"Клима-систем", cena:360000,
262	   opis:"Ја намалува шансата за штетници за 60%."},
263	  {id:"sushara", ime:"Професионална сушара", cena:300000,
264	   opis:"Сушењето е 40% побрзо, а идеалниот прозорец се шири на 8–14 дена."},
265	  {id:"rabotnik", ime:"Вработен работник", cena:900000,
266	   opis:"Автоматски ѓубри кога хранливите материи ќе паднат под 40%."}
267	];
268	
269	const NASTANI = [
270	  {id:"grini",  ime:"Пајакови грини",      ikona:"🕷️", steta:0.9, tretman:"Акарицид",   cena:900, samoCvetanje:false},
271	  {id:"muvla",  ime:"Мувла",               ikona:"🍄", steta:1.4, tretman:"Фунгицид",   cena:1400, samoCvetanje:true},
272	  {id:"voshki", ime:"Лисни вошки",         ikona:"🐛", steta:0.6, tretman:"Инсектицид", cena:700,  samoCvetanje:false},
273	  {id:"azot",   ime:"Недостаток на азот",  ikona:"🍂", steta:0.5, tretman:null,         cena:0,   samoCvetanje:false}
274	];
275	
276	const OCENKI = [
277	  {prag:85, ime:"Врвен",   klasa:"o-vrven",   mult:2.2},
278	  {prag:70, ime:"Одличен", klasa:"o-odlicen", mult:1.6},
279	  {prag:50, ime:"Среден",  klasa:"o-sreden",  mult:1.1},
280	  {prag:0,  ime:"Слаб",    klasa:"o-slab",    mult:0.6}
281	];
282	
283	const FAZI = {
284	  NIKNENJE:   {ime:"Никнење"},
285	  VEGETACIJA: {ime:"Вегетација"},
286	  CVETANJE:   {ime:"Цветање"},
287	  ZRELO:      {ime:"Зрело за берба"}
288	};
289	
290	const TEKST = {
291	  nemaPari:"Немаш доволно денари.",
292	  nemaSemki:"Немаш семки. Купи од продавницата.",
293	  potrebnoNivo:n=>`Потребно е ниво ${n}.`,
294	  kupenoSeme:s=>`Купено семе: ${s}.`,
295	  zasadeno:s=>`Засадено: ${s}.`,
296	  polevanje:"Полеано. 💧",
297	  hranenje:"Наѓубрено. 🌱",
298	  tretirano:t=>`Применето: ${t}.`,
299	  samoGubrenje:"Ова се лекува со ѓубрење, не со третман.",
300	  berba:(g,s)=>`Берба на ${s}: ${g} г мокра маса. Оди во сушара.`,
301	  sushenjeGotovo:(g,o)=>`Сушењето заврши: ${g} г, оценка „${o}".`,
302	  prodadeno:(g,p)=>`Продадени ${g} г за ${formatPari(p)} ден.`,
303	  analiza:t=>`Анализата е готова: ${t}% ТХЦ. Сертифициран производ.`,
304	  novoNivo:n=>`🎉 Ново ниво: ${n}!`,
305	  novaLeja:"Нова леја е отклучена!",
306	  kupenaNadgradba:i=>`Купено: ${i}.`,
307	  sejvGreska:"Зачувувањето не успеа — играта продолжува во меморија.",
308	  vcitajGreska:"Оштетена зачувана игра — почнуваме одново.",
309	  starVerzija:"Зачуваната игра е од стара верзија — почнуваме одново.",
310	  prezrelo:"⚠️ Растението презрева — квалитетот паѓа!"
311	};
312	
313	/* ═══════════════════════════════════════════════════════════════
314	   3. СОСТОЈБА
315	   ═══════════════════════════════════════════════════════════════ */
316	let sostojba;
317	let brojacTikovi = 0;
318	let aktivnoJazice = "prodavnica";
319	let panelValjaSe = true;         // dirty flag за страничниот панел
320	let posledenTajmer = 0;
321	let sledenId = 1;
322	
323	function novaIgra(){
324	  const pazar = {};
325	  SORTI.forEach(s => { pazar[s.id] = 1.0; });
326	  return {
327	    verzija: KONFIG.VERZIJA,
328	    parichnik: KONFIG.POCETNI_PARI,
329	    nivo: 1, iskustvo: 0,
330	    den: 1, chas: 6,
331	    brojLei: KONFIG.POCETNI_LEI,
332	    lei: Array.from({length: KONFIG.MAX_LEI}, () => ({rastenie: null})),
333	    semki: {skopsko: 1},
334	    lampa: 0,
335	    nadgradbi: {navodnuvanje:false, klima:false, sushara:false, rabotnik:false},
336	    sushara: [],
337	    magacin: [],
338	    pazar,
339	    statistika: {vkupnoBerbi:0, vkupnoGrama:0, vkupnoZaraboteno:0}
340	  };
341	}
