343	/* ═══════════════════════════════════════════════════════════════
344	   4. ПОМОШНИ ФУНКЦИИ
345	   ═══════════════════════════════════════════════════════════════ */
346	const stegni = (v, min, max) => Math.min(max, Math.max(min, v));
347	const najdiSorta  = id => SORTI.find(s => s.id === id);
348	const najdiNastan = id => NASTANI.find(n => n.id === id);
349	const tekovnaLampa = () => LAMPI[stegni(sostojba.lampa, 0, LAMPI.length - 1)];
350	const formatPari = n => Math.round(n).toLocaleString("mk-MK");
351	const potrebnoIskustvo = nivo => Math.round(500 * Math.pow(nivo, 1.5));
352	
353	function najdiOcenka(kvalitet){
354	  return OCENKI.find(o => kvalitet >= o.prag) || OCENKI[OCENKI.length - 1];
355	}
356	
357	/** Вкупно игрални часови од семка до зрелост, за дадена сорта. */
358	function vkupnoChasaDoZrelost(sorta){
359	  return (KONFIG.CHASA_NIKNENJE + KONFIG.CHASA_VEGETACIJA + KONFIG.CHASA_CVETANJE) * sorta.traenje;
360	}
