388	/* ═══════════════════════════════════════════════════════════════
389	   5. ПРЕСМЕТКИ — чисти функции, без странични ефекти
390	   ═══════════════════════════════════════════════════════════════ */
391	
392	/** Сува маса во грамови од една берба. */
393	function presmetajPrinos(sorta, prosekZdravje, lampa){
394	  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
395	  return sorta.prinos * Math.pow(zdrav, 1.2) * lampa.prinosMult;
396	}
397	
398	/**
399	 * ╔══════════════════════════════════════════════════════════════╗
400	 * ║  ОВА Е ГЛАВНОТО КОПЧЕ ЗА БАЛАНС НА ИГРАТА.                   ║
401	 * ║  Слободно замени го телото — потписот останува ист.          ║
402	 * ╚══════════════════════════════════════════════════════════════╝
403	 *
404	 * Враќа квалитет 0–100, кој потоа станува оценка (Врвен → Слаб)
405	 * и директно ја множи продажната цена.
406	 *
407	 * @param {number} prosekZdravje    0–100, просечно здравје низ целиот живот
408	 * @param {number} tochnostSushenje 0–1,  1.0 = совршено погоден прозорец за сушење
409	 * @param {number} genetika         0–1,  вродениот потенцијал на сортата
410	 * @param {number} lampaBonus       0–14, бонус од ламбата
411	 * @param {number} deoviSoStetnik   цели денови поминати со нетретиран штетник
412	 * @returns {number} квалитет 0–100
413	 *
414	 * TODO(ти):  Ова е компромис меѓу ДВЕ различни игри и одлуката е твоја:
415	 *
416	 *   А) „Наградувај трпение" — дај му голема тежина на `tochnostSushenje`
417	 *      и остра казна за `deoviSoStetnik`. Играчот што внимава на секое
418	 *      растение заработува многукратно повеќе од оној што сади масовно.
419	 *
420	 *   Б) „Наградувај обем" — дај му поголема тежина на `genetika` и
421	 *      `lampaBonus`, а помала на грижата. Тогаш вистинската стратегија
422	 *      е да купуваш подобри семки и повеќе леи, а не да кликаш.
423	 *
424	 * Долунаведената имплементација е намерно во средина (грижата носи
425	 * најмногу, но генетиката поставува таван), за играта да е играбилна
426	 * веднаш. Замени ја кога ќе решиш во која насока ја сакаш играта.
427	 */
428	function presmetajKvalitet(prosekZdravje, tochnostSushenje, genetika, lampaBonus, deoviSoStetnik){
429	  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
430	  const suvo  = stegni(tochnostSushenje, 0, 1);
431	  const gen   = stegni(genetika, 0, 1);
432	
433	  // Грижата е основата (0–60), сушењето ја модулира.
434	  const osnova = 60 * Math.pow(zdrav, 1.1) * (0.55 + 0.45 * suvo);
435	  // Генетиката поставува таван кон кој се стреми резултатот (0–30).
436	  const taban  = 30 * gen;
437	  // Опремата е мал, но сигурен додаток.
438	  const oprema = stegni(lampaBonus, 0, 14);
439	  // Секој ден со штетник боли трајно.
440	  const kazna  = Math.max(0, deoviSoStetnik) * 2.5;
441	
442	  return stegni(osnova + taban + oprema - kazna, 0, 100);
443	}
444	
445	/** Претвора поминати денови сушење во точност 0–1 (види §5 од спецификацијата). */
446	function tochnostOdSushenje(denovi, imaSushara){
447	  const d1 = imaSushara ? 8 : 9;      // прв идеален ден
448	  const d2 = imaSushara ? 14 : 12;    // последен идеален ден
449	  if (denovi <  d1)     return 0.55;  // предвреме
450	  if (denovi <= d2)     return 1.00;  // идеално
451	  if (denovi <= d2 + 4) return 0.80;  // прифатливо
452	  return 0.65;                        // пресушено
453	}
454	
455	/** ТХЦ процент, изведен од квалитетот и генетиката. */
456	function presmetajTHC(kvalitet, genetika){
457	  return +(8 + 22 * genetika * (stegni(kvalitet, 0, 100) / 100)).toFixed(1);
458	}
