460	/* ═══════════════════════════════════════════════════════════════
461	   6. МОТОР — еден тик ја движи целата игра
462	   ═══════════════════════════════════════════════════════════════ */
463	function tikni(){
464	  const prethodenDen = sostojba.den;
465	
466	  // ── Часовник ──────────────────────────────────────────────
467	  sostojba.chas += KONFIG.CHASA_PO_TIK;
468	  while (sostojba.chas >= 24){ sostojba.chas -= 24; sostojba.den++; }
469	  const novDen = sostojba.den !== prethodenDen;
470	
471	  const lampa = tekovnaLampa();
472	  const delDena = KONFIG.CHASA_PO_TIK / 24;   // колку од денот помина овој тик
473	
474	  // ── Растенија ─────────────────────────────────────────────
475	  for (let i = 0; i < sostojba.brojLei; i++){
476	    const r = sostojba.lei[i].rastenie;
477	    if (!r) continue;
478	    const sorta = najdiSorta(r.sorta);
479	    if (!sorta) continue;
480	
481	    r.vozrast += KONFIG.CHASA_PO_TIK;
482	    r.brojTikovi++;
483	
484	    // Потрошувачка на вода и храна
485	    r.voda    = stegni(r.voda    - KONFIG.VODA_PAD_DEN  * delDena, 0, 100);
486	    r.hraniva = stegni(r.hraniva - KONFIG.HRANA_PAD_DEN * delDena, 0, 100);
487	
488	    // Автоматика од надградбите
489	    if (sostojba.nadgradbi.navodnuvanje && r.voda < KONFIG.AVTO_VODA_PRAG)
490	      r.voda = KONFIG.AVTO_VODA_PRAG;
491	    if (sostojba.nadgradbi.rabotnik && r.hraniva < KONFIG.RABOTNIK_PRAG){
492	      r.hraniva = stegni(r.hraniva + KONFIG.HRANA_DOZA, 0, 100);
493	      if (r.stetnik === "azot") r.stetnik = null;
494	    }
495	
496	    // ── Здравје ───────────────────────────────────────────
497	    let delta = 0, dobro = true;
498	    if (r.voda    < KONFIG.VODA_MIN) { delta -= KONFIG.STETA_SUSA;    dobro = false; }
499	    if (r.voda    > KONFIG.VODA_MAX) { delta -= KONFIG.STETA_DAVENJE; dobro = false; }
500	    if (r.hraniva < KONFIG.HRANA_MIN){ delta -= KONFIG.STETA_GLAD;    dobro = false; }
501	    if (r.hraniva > KONFIG.HRANA_MAX){ delta -= KONFIG.STETA_PREGOR;  dobro = false; }
502	
503	    if (r.stetnik){
504	      const n = najdiNastan(r.stetnik);
505	      if (n){ delta -= n.steta; dobro = false; }
506	      r.deoviSoStetnik += delDena;
507	    }
508	    if (dobro) delta += KONFIG.OPORAVUVANJE;
509	
510	    r.zdravje = stegni(r.zdravje + delta, 0, 100);
511	    r.zbirZdravje += r.zdravje;
512	
513	    // ── Фаза ──────────────────────────────────────────────
514	    const t = sorta.traenje;
515	    const kNikn = KONFIG.CHASA_NIKNENJE * t;
516	    const kVeg  = kNikn + KONFIG.CHASA_VEGETACIJA * t;
517	    const kCvet = kVeg  + KONFIG.CHASA_CVETANJE  * t;
518	
519	    if      (r.vozrast < kNikn) r.faza = "NIKNENJE";
520	    else if (r.vozrast < kVeg)  r.faza = "VEGETACIJA";
521	    else if (r.vozrast < kCvet) r.faza = "CVETANJE";
522	    else {
523	      r.faza = "ZRELO";
524	      const preku = r.vozrast - kCvet - KONFIG.CHASA_ZRELO_PROZOR;
525	      if (preku > 0){
526	        // Презревањето трајно го симнува квалитетот преку здравјето
527	        r.zdravje = stegni(r.zdravje - KONFIG.KAZNA_PREZRELOST_DEN * delDena, 0, 100);
528	        if (!r.predupredenoPrezrelost){
529	          r.predupredenoPrezrelost = true;
530	          izvesti(TEKST.prezrelo, "greska");
531	        }
532	      }
533	    }
534	
535	    // ── Штетници ──────────────────────────────────────────
536	    if (!r.stetnik){
537	      let sansa = KONFIG.SANSA_STETNIK_DEN * delDena;
538	      if (sostojba.nadgradbi.klima) sansa *= KONFIG.KLIMA_NAMALUVANJE;
539	      if (Math.random() < sansa){
540	        const mozni = NASTANI.filter(n => !n.samoCvetanje || r.faza === "CVETANJE");
541	        r.stetnik = mozni[Math.floor(Math.random() * mozni.length)].id;
542	        panelValjaSe = true;
543	      }
544	    }
545	  }
546	
547	  // ── Сушара ────────────────────────────────────────────────
548	  // Панелот се освежува само кога ќе се смени ЦЕЛ ден, инаку би се
549	  // прецртувал 4 пати во секунда и постојано би го ресетирал скролот.
550	  const brzina = sostojba.nadgradbi.sushara ? KONFIG.SUSHARA_ZABRZUVANJE : 1;
551	  for (const serija of sostojba.sushara){
552	    const prethoden = Math.floor(serija.denovi);
553	    serija.denovi += delDena * brzina;
554	    if (Math.floor(serija.denovi) !== prethoden) panelValjaSe = true;
555	  }
556	
557	  // ── Пазар — еднаш дневно ──────────────────────────────────
558	  if (novDen){
559	    for (const s of SORTI){
560	      const drift = 1 + (Math.random() - 0.5) * 2 * KONFIG.PAZAR_DRIFT;
561	      sostojba.pazar[s.id] = stegni((sostojba.pazar[s.id] || 1) * drift,
562	                                     KONFIG.PAZAR_MIN, KONFIG.PAZAR_MAX);
563	    }
564	    panelValjaSe = true;
565	  }
566	
567	  // ── Зачувување ────────────────────────────────────────────
568	  if (++brojacTikovi % KONFIG.AVTOSEJV_TIKOVI === 0) zachuvaj();
569	}
