574	function kupiSeme(id){
575	  const s = najdiSorta(id);
576	  if (!s) return;
577	  if (sostojba.nivo < s.nivo){ izvesti(TEKST.potrebnoNivo(s.nivo), "greska"); return; }
578	  if (!naplati(s.cena)) return;
579	  sostojba.semki[id] = (sostojba.semki[id] || 0) + 1;
580	  izvesti(TEKST.kupenoSeme(s.ime));
581	  panelValjaSe = true;
582	  iscrtajSe();
583	}
