636	function nahrani(indeks){
637	  const r = sostojba.lei[indeks].rastenie; if (!r) return;
638	  if (!naplati(KONFIG.CENA_HRANA)) return;
639	  r.hraniva = stegni(r.hraniva + KONFIG.HRANA_DOZA, 0, 100);
640	  if (r.stetnik === "azot") r.stetnik = null;   // азотот се лекува со ѓубрење
641	  izvesti(TEKST.hranenje);
642	  iscrtajSe();
