645	function tretiraj(indeks){
646	  const r = sostojba.lei[indeks].rastenie; if (!r || !r.stetnik) return;
647	  const n = najdiNastan(r.stetnik); if (!n){ r.stetnik = null; return; }
648	  if (!n.tretman){ izvesti(TEKST.samoGubrenje, "greska"); return; }
649	  if (!naplati(n.cena)) return;
650	  r.stetnik = null;
651	  izvesti(TEKST.tretirano(n.tretman));
652	  iscrtajSe();
