655	function oberi(indeks){
656	  const r = sostojba.lei[indeks].rastenie; if (!r || r.faza !== "ZRELO") return;
657	  const sorta = najdiSorta(r.sorta); if (!sorta) return;
658	
659	  const prosekZdravje = r.brojTikovi > 0 ? r.zbirZdravje / r.brojTikovi : 0;
660	  const suvo   = presmetajPrinos(sorta, prosekZdravje, tekovnaLampa());
661	  const vlazno = suvo / KONFIG.VLAZNO_VO_SUVO;
662	
663	  sostojba.sushara.push({
664	    id: sledenId++, sorta: r.sorta,
665	    gramaVlazno: vlazno, denovi: 0,
666	    prosekZdravje, deoviSoStetnik: r.deoviSoStetnik
667	  });
668	  sostojba.lei[indeks].rastenie = null;
669	  sostojba.statistika.vkupnoBerbi++;
670	
671	  izvesti(TEKST.berba(Math.round(vlazno), sorta.ime), "pari");
672	  aktivnoJazice = "sushara";
673	  panelValjaSe = true;
674	  iscrtajSe();
675	}
