677	function zavrsiSushenje(serijaId){
678	  const idx = sostojba.sushara.findIndex(s => s.id === serijaId);
679	  if (idx === -1) return;
680	  const serija = sostojba.sushara[idx];
681	  const sorta = najdiSorta(serija.sorta); if (!sorta) return;
682	
683	  const tochnost = tochnostOdSushenje(Math.floor(serija.denovi), sostojba.nadgradbi.sushara);
684	  const kvalitet = presmetajKvalitet(
685	    serija.prosekZdravje, tochnost, sorta.genetika,
686	    tekovnaLampa().kvalitetBonus, Math.floor(serija.deoviSoStetnik)
687	  );
688	  const ocenka = najdiOcenka(kvalitet);
689	  const grama  = serija.gramaVlazno * KONFIG.VLAZNO_VO_SUVO;
690	
691	  sostojba.magacin.push({
692	    id: sledenId++, sorta: serija.sorta,
693	    grama, kvalitet, ocenka: ocenka.ime, ocenkaMult: ocenka.mult,
694	    klasa: ocenka.klasa, thc: null, testirano: false
695	  });
696	  sostojba.sushara.splice(idx, 1);
697	  sostojba.statistika.vkupnoGrama += grama;
698	
699	  izvesti(TEKST.sushenjeGotovo(Math.round(grama), ocenka.ime), "pari");
700	  aktivnoJazice = "magacin";
701	  panelValjaSe = true;
702	  iscrtajSe();
703	}
704	
705	function testirajVoLaboratorija(serijaId){
706	  const p = sostojba.magacin.find(m => m.id === serijaId);
707	  if (!p || p.testirano) return;
708	  const sorta = najdiSorta(p.sorta); if (!sorta) return;
709	  if (!naplati(KONFIG.CENA_LABORATORIJA)) return;
710	  p.thc = presmetajTHC(p.kvalitet, sorta.genetika);
711	  p.testirano = true;
712	  izvesti(TEKST.analiza(p.thc), "pari");
713	  panelValjaSe = true;
714	  iscrtajSe();
715	}
716	
717	function cenaNaSerija(p){
718	  const sorta = najdiSorta(p.sorta); if (!sorta) return 0;
719	  const pazar = sostojba.pazar[p.sorta] || 1;
720	  return p.grama * sorta.cenaPoGram * pazar * p.ocenkaMult
721	         * (p.testirano ? KONFIG.BONUS_LABORATORIJA : 1);
722	}
723	
724	function prodaj(serijaId){
725	  const idx = sostojba.magacin.findIndex(m => m.id === serijaId);
726	  if (idx === -1) return;
727	  const p = sostojba.magacin[idx];
728	  const pari = cenaNaSerija(p);
729	
730	  sostojba.parichnik += pari;
731	  sostojba.statistika.vkupnoZaraboteno += pari;
