879	function iscrtajLeja(i){
880	  const j = lejaJazli[i];
881	  const otklucena = i < sostojba.brojLei;
882	  const r = sostojba.lei[i].rastenie;
883	
884	  // Прикажи ги отклучените леи плус ЕДНА следна, како понуда за купување.
885	  j.koren.style.display = (otklucena || i === sostojba.brojLei) ? "" : "none";
886	
887	  // ── Заклучена леја ──────────────────────────────────────
888	  if (!otklucena){
889	    j.koren.className = "leja zaklucena";
890	    j.faza.textContent = "";
891	    j.znakSorta.textContent = "";
892	    j.znakStetnik.textContent = "";
893	    j.prazna.textContent = "🔒 Заклучена леја";
894	    j.prazna.style.display = "";
895	    skrijRastenie(j);
896	    postaviAkcii(j, sostojba.brojLei < KONFIG.MAX_LEI
897	      ? `<button class="glavna" onclick="otkluchiLeja()">Отклучи · ${formatPari(cenaNaSlednaLeja())} ден</button>`
898	      : "");
899	    isprazniLenti(j, "");
900	    return;
901	  }
902	
903	  // ── Празна леја ─────────────────────────────────────────
904	  if (!r){
905	    j.koren.className = "leja";
906	    j.faza.textContent = "Празна";
907	    j.znakSorta.textContent = "";
908	    j.znakStetnik.textContent = "";
909	    j.prazna.textContent = "🌱 Празна леја";
910	    j.prazna.style.display = "";
911	    skrijRastenie(j);
912	    postaviAkcii(j, `<button class="glavna" onclick="otvoriIzborSeme(${i})">Засади</button>`);
913	    isprazniLenti(j, "—");
914	    return;
915	  }
916	
917	  // ── Засадена леја ───────────────────────────────────────
918	  const sorta = najdiSorta(r.sorta);
919	  const zrela = r.faza === "ZRELO";
920	  const bolna = r.zdravje < 45 || !!r.stetnik;
921	  j.koren.className = "leja" + (zrela ? " zrela" : "") + (bolna ? " bolna" : "");
922	  j.faza.textContent = FAZI[r.faza] ? FAZI[r.faza].ime : "—";
923	  j.prazna.style.display = "none";
924	  j.znakSorta.textContent = sorta ? sorta.ime : "?";
925	
926	  if (r.stetnik){
927	    const n = najdiNastan(r.stetnik);
928	    j.znakStetnik.textContent = n ? n.ikona : "⚠️";
929	    j.znakStetnik.title = n ? n.ime : "";
930	  } else {
931	    j.znakStetnik.textContent = "";
932	    j.znakStetnik.title = "";
933	  }
934	
935	  // Геометрија на растот
936	  const traenje = sorta ? sorta.traenje : 1;
937	  const vkupno = sorta ? vkupnoChasaDoZrelost(sorta) : 1;
938	  const rast = stegni(r.vozrast / vkupno, 0, 1);
939	  const zdr  = r.zdravje / 100;
940	
941	  const visina = 8 + 76 * rast;
942	  j.steblo.setAttribute("height", visina.toFixed(1));
943	  j.steblo.setAttribute("y", (118 - visina).toFixed(1));
944	  j.lisja.forEach((g, idx) => {
945	    // Долниот пар расте прв, горниот последен
946	    const prag = idx * 0.22;
947	    const lokalno = stegni((rast - prag) / 0.45, 0, 1);
948	    const y = Number(g.dataset.y) - 34 * rast;
949	    g.style.transform = `translate(50px,${y.toFixed(1)}px) scale(${lokalno.toFixed(3)})`;
950	  });
951	
952	  const pochetokCvet = (KONFIG.CHASA_NIKNENJE + KONFIG.CHASA_VEGETACIJA) * traenje;
953	  const cvet = (r.faza === "CVETANJE" || zrela)
954	    ? stegni((r.vozrast - pochetokCvet) / (KONFIG.CHASA_CVETANJE * traenje), 0, 1)
955	    : 0;
956	  j.pupki.setAttribute("opacity", cvet.toFixed(2));
957	
958	  // Бојата паѓа од зелена кон кафеава како што паѓа здравјето
959	  const nijansa = 25 + 85 * zdr, zasit = 30 + 50 * zdr, svetlo = 22 + 18 * zdr;
960	  j.boja.setAttribute("fill",
961	    `hsl(${nijansa.toFixed(0)} ${zasit.toFixed(0)}% ${svetlo.toFixed(0)}%)`);
962	
963	  // Ленти
964	  postaviLenta(j.bVoda, j.uVoda, r.voda,
965	    (r.voda < KONFIG.VODA_MIN || r.voda > KONFIG.VODA_MAX) ? "var(--crvena)" : "var(--sina)");
966	  postaviLenta(j.bHrana, j.uHrana, r.hraniva,
967	    (r.hraniva < KONFIG.HRANA_MIN || r.hraniva > KONFIG.HRANA_MAX) ? "var(--crvena)" : "var(--zelena)");
968	  postaviLenta(j.bZdravje, j.uZdravje, r.zdravje,
969	    r.zdravje < 45 ? "var(--crvena)" : r.zdravje < 75 ? "var(--zlato)" : "var(--zelena)");
970	
971	  // Дугмиња
972	  let html = "";
973	  if (zrela) html += `<button class="zlatna" onclick="oberi(${i})">🌾 Обери</button>`;
974	  html += `<button onclick="polej(${i})">💧 Полеј</button>`;
975	  html += `<button onclick="nahrani(${i})">🌱 ${KONFIG.CENA_HRANA} ден</button>`;
976	  if (r.stetnik){
977	    const n = najdiNastan(r.stetnik);
978	    html += (n && n.tretman)
979	      ? `<button class="opasna" onclick="tretiraj(${i})">${n.tretman} · ${n.cena} ден</button>`
980	      : `<button class="opasna" onclick="nahrani(${i})">Ѓубри против азот</button>`;
981	  }
982	  postaviAkcii(j, html);
983	}
